/// The type of a bound expression node. The values mirror the engine's own expression types, restricted to the
pub type EXPRESSION_TYPE = i32;
/// A node type this API does not model. Its children can still be walked.
pub const EXPRESSION_TYPE_INVALID: EXPRESSION_TYPE = 0;
/// A cast. One child; the target type is the node's return type and `[[expression_cast_get_mode]]` tells a `TRY_CAST` apart.
pub const EXPRESSION_TYPE_OPERATOR_CAST: EXPRESSION_TYPE = 12;
/// Logical `NOT`. One child.
pub const EXPRESSION_TYPE_OPERATOR_NOT: EXPRESSION_TYPE = 13;
/// `IS NULL`. One child.
pub const EXPRESSION_TYPE_OPERATOR_IS_NULL: EXPRESSION_TYPE = 14;
/// `IS NOT NULL`. One child.
pub const EXPRESSION_TYPE_OPERATOR_IS_NOT_NULL: EXPRESSION_TYPE = 15;
/// `=`. Two children.
pub const EXPRESSION_TYPE_COMPARE_EQUAL: EXPRESSION_TYPE = 25;
/// `<>`. Two children.
pub const EXPRESSION_TYPE_COMPARE_NOTEQUAL: EXPRESSION_TYPE = 26;
/// `<`. Two children.
pub const EXPRESSION_TYPE_COMPARE_LESSTHAN: EXPRESSION_TYPE = 27;
/// `>`. Two children.
pub const EXPRESSION_TYPE_COMPARE_GREATERTHAN: EXPRESSION_TYPE = 28;
/// `<=`. Two children.
pub const EXPRESSION_TYPE_COMPARE_LESSTHANOREQUALTO: EXPRESSION_TYPE = 29;
/// `>=`. Two children.
pub const EXPRESSION_TYPE_COMPARE_GREATERTHANOREQUALTO: EXPRESSION_TYPE = 30;
/// `IN`. The first child is the value tested, the remaining children are the candidates.
pub const EXPRESSION_TYPE_COMPARE_IN: EXPRESSION_TYPE = 35;
/// `NOT IN`. The first child is the value tested, the remaining children are the candidates.
pub const EXPRESSION_TYPE_COMPARE_NOT_IN: EXPRESSION_TYPE = 36;
/// `IS DISTINCT FROM`. Two children.
pub const EXPRESSION_TYPE_COMPARE_DISTINCT_FROM: EXPRESSION_TYPE = 37;
/// `BETWEEN`. Three children: the value tested, the lower bound and the upper bound.
pub const EXPRESSION_TYPE_COMPARE_BETWEEN: EXPRESSION_TYPE = 38;
/// `IS NOT DISTINCT FROM`. Two children.
pub const EXPRESSION_TYPE_COMPARE_NOT_DISTINCT_FROM: EXPRESSION_TYPE = 40;
/// Logical `AND`. Two or more children.
pub const EXPRESSION_TYPE_CONJUNCTION_AND: EXPRESSION_TYPE = 50;
/// Logical `OR`. Two or more children.
pub const EXPRESSION_TYPE_CONJUNCTION_OR: EXPRESSION_TYPE = 51;
/// A constant. No children; read it with `[[expression_constant_get_value]]`.
pub const EXPRESSION_TYPE_VALUE_CONSTANT: EXPRESSION_TYPE = 75;
/// A prepared statement parameter whose value is not known yet. No children.
pub const EXPRESSION_TYPE_VALUE_PARAMETER: EXPRESSION_TYPE = 76;
/// A call to a scalar function other than the ones listed above. The children are its arguments; read the name with `[[expression_function_get_name]]`.
pub const EXPRESSION_TYPE_BOUND_FUNCTION: EXPRESSION_TYPE = 141;
/// A `CASE` expression. The children are each `WHEN` condition followed by its `THEN` result, then the `ELSE` result.
pub const EXPRESSION_TYPE_CASE_EXPR: EXPRESSION_TYPE = 150;
/// `COALESCE`. One or more children.
pub const EXPRESSION_TYPE_OPERATOR_COALESCE: EXPRESSION_TYPE = 152;
/// A reference to a column. No children; read it with `[[expression_column_ref_get_index]]`.
pub const EXPRESSION_TYPE_BOUND_COLUMN_REF: EXPRESSION_TYPE = 228;

/// How `[[file_system_open]]` opens a file. These are not a bitmask -- apply
pub type FILE_FLAG = i32;
/// Not a flag. The zero value, so that an uninitialized variable does not name a behaviour; applying it is an error.
pub const FILE_FLAG_INVALID: FILE_FLAG = 0;
/// Open the file with "read" capabilities.
pub const FILE_FLAG_READ: FILE_FLAG = 1;
/// Open the file with "write" capabilities.
pub const FILE_FLAG_WRITE: FILE_FLAG = 2;
/// Create the file if it does not exist, and open it as it is if it does.
pub const FILE_FLAG_CREATE: FILE_FLAG = 3;
/// Create the file if it does not exist, and truncate it to empty if it does. To fail instead of truncating, combine `FILE_FLAG_CREATE` with `FILE_FLAG_EXCLUSIVE_CREATE`.
pub const FILE_FLAG_CREATE_NEW: FILE_FLAG = 4;
/// Open the file in "append" mode.
pub const FILE_FLAG_APPEND: FILE_FLAG = 5;
/// Fail if the file already exists. A modifier on `FILE_FLAG_CREATE`, and meaningless without it.
pub const FILE_FLAG_EXCLUSIVE_CREATE: FILE_FLAG = 6;
/// The file will be read and written at explicit offsets from several threads at once. Pass it whenever
pub const FILE_FLAG_PARALLEL_ACCESS: FILE_FLAG = 7;
/// Read the file through DuckDB's external file cache, which keeps the bytes that were read in memory, so
pub const FILE_FLAG_EXTERNAL_FILE_CACHE: FILE_FLAG = 8;

/// The mode a cast is being executed in. A normal cast must either succeed
pub type CAST_MODE = i32;
/// A regular cast. A conversion failure reported through the error slot aborts the query.
pub const CAST_MODE_NORMAL: CAST_MODE = 0;
/// A "try" cast. Conversion failures should be written as NULLs into the output vector; an error reported through the slot is swallowed and the affected rows are left NULL.
pub const CAST_MODE_TRY: CAST_MODE = 1;

/// The kind of a macro function, deciding how its body is read. Pass one to `[[macro_function_create]]`.
pub type MACRO_FUNCTION_TYPE = i32;
/// A scalar macro. The body is a single expression, and the macro is called like a scalar function.
pub const MACRO_FUNCTION_TYPE_SCALAR: MACRO_FUNCTION_TYPE = 0;
/// A table macro. The body is a single SELECT query, and the macro is called like a table function.
pub const MACRO_FUNCTION_TYPE_TABLE: MACRO_FUNCTION_TYPE = 1;

/// Identifies a configurable function property. Pass one of these to
pub type FUNCTION_PROPERTY_KEY = i32;
/// How stable/deterministic the function's result is across rows and queries. Accepts the `FUNCTION_PROPERTY_STABILITY_*` values. Defaults to `CONSISTENT`.
pub const FUNCTION_PROPERTY_STABILITY: FUNCTION_PROPERTY_KEY = 65536;
/// Whether the function handles NULL inputs itself. Accepts the `FUNCTION_PROPERTY_NULL_HANDLING_*` values. Defaults to `DEFAULT` (NULL in, NULL out).
pub const FUNCTION_PROPERTY_NULL_HANDLING: FUNCTION_PROPERTY_KEY = 65792;
/// Whether the function can raise a runtime error. Accepts the `FUNCTION_PROPERTY_FALLIBILITY_*` values. Functions created through this API default to `FALLIBLE`, since their callbacks can report errors.
pub const FUNCTION_PROPERTY_FALLIBILITY: FUNCTION_PROPERTY_KEY = 66048;
/// How the function interacts with collations on its arguments. Accepts the `FUNCTION_PROPERTY_COLLATION_HANDLING_*` values. Defaults to `PROPAGATE`.
pub const FUNCTION_PROPERTY_COLLATION_HANDLING: FUNCTION_PROPERTY_KEY = 66304;
/// Aggregate only. Whether the aggregate's result depends on the order in which rows are aggregated. Accepts the `FUNCTION_PROPERTY_AGG_ORDER_DEPENDENT_*` values. Defaults to `YES`.
pub const FUNCTION_PROPERTY_AGG_ORDER_DEPENDENT: FUNCTION_PROPERTY_KEY = 196608;
/// Aggregate only. Whether the aggregate's result is affected by a DISTINCT modifier. Accepts the `FUNCTION_PROPERTY_AGG_DISTINCT_DEPENDENT_*` values. Defaults to `YES`.
pub const FUNCTION_PROPERTY_AGG_DISTINCT_DEPENDENT: FUNCTION_PROPERTY_KEY = 196864;

/// A value for a `[[FUNCTION_PROPERTY_KEY]]`. Each key owns a 256-value block: a
pub type FUNCTION_PROPERTY_VALUE = i32;
/// The function always returns the same result given the same input.
pub const FUNCTION_PROPERTY_STABILITY_CONSISTENT: FUNCTION_PROPERTY_VALUE = 65536;
/// The result may differ per row (e.g. random()).
pub const FUNCTION_PROPERTY_STABILITY_VOLATILE: FUNCTION_PROPERTY_VALUE = 65537;
/// The result is stable within a single query/transaction but may change across queries (e.g. now()).
pub const FUNCTION_PROPERTY_STABILITY_CONSISTENT_WITHIN_QUERY: FUNCTION_PROPERTY_VALUE = 65538;
/// Default NULL handling: if any argument is NULL the result is NULL and the function is not invoked for that row.
pub const FUNCTION_PROPERTY_NULL_HANDLING_DEFAULT: FUNCTION_PROPERTY_VALUE = 65792;
/// The function handles NULL inputs itself and is invoked even when arguments are NULL.
pub const FUNCTION_PROPERTY_NULL_HANDLING_SPECIAL: FUNCTION_PROPERTY_VALUE = 65793;
/// The function never raises a runtime error. Declaring this promises that the callbacks never report an error; an error reported anyway becomes an internal error.
pub const FUNCTION_PROPERTY_FALLIBILITY_INFALLIBLE: FUNCTION_PROPERTY_VALUE = 66048;
/// The function may raise a runtime error for some inputs.
pub const FUNCTION_PROPERTY_FALLIBILITY_FALLIBLE: FUNCTION_PROPERTY_VALUE = 66049;
/// The function combines collations from its inputs and propagates them to its result (default).
pub const FUNCTION_PROPERTY_COLLATION_HANDLING_PROPAGATE: FUNCTION_PROPERTY_VALUE = 66304;
/// Combinable collations are executed on the input arguments before the function runs.
pub const FUNCTION_PROPERTY_COLLATION_HANDLING_PUSH_COMBINABLE: FUNCTION_PROPERTY_VALUE = 66305;
/// Collations are ignored by the function.
pub const FUNCTION_PROPERTY_COLLATION_HANDLING_IGNORE: FUNCTION_PROPERTY_VALUE = 66306;
/// The aggregate's result depends on the order in which rows are aggregated (default).
pub const FUNCTION_PROPERTY_AGG_ORDER_DEPENDENT_YES: FUNCTION_PROPERTY_VALUE = 196608;
/// The aggregate's result does not depend on input order.
pub const FUNCTION_PROPERTY_AGG_ORDER_DEPENDENT_NO: FUNCTION_PROPERTY_VALUE = 196609;
/// The aggregate's result is affected by a DISTINCT modifier (default).
pub const FUNCTION_PROPERTY_AGG_DISTINCT_DEPENDENT_YES: FUNCTION_PROPERTY_VALUE = 196864;
/// The aggregate's result is not affected by a DISTINCT modifier.
pub const FUNCTION_PROPERTY_AGG_DISTINCT_DEPENDENT_NO: FUNCTION_PROPERTY_VALUE = 196865;

